test('short-circuits in declaration order so skipped children never error', () => {
  const input = { a: 1, bad: {} };
  assert.equal(branchOf({ all: [{ field: 'a', operator: 'gte', value: 5 }, { field: 'bad', operator: 'gte', value: 0 }] }, input), 'failed');
