import('./src/engine.js').then(({ executeWorkflow, validateWorkflow }) => {
  const assert = (cond, msg) => { if (!cond) { console.error('FAIL:', msg); process.exitCode = 1; } };

  // empty dependsOn array is a no-op: multi-end legacy workflow still valid
  const legacy = { id: 'w', entry: 'a', nodes: [
    { id: 'a', type: 'trigger', next: 'b', dependsOn: [] },
    { id: 'b', type: 'condition', condition: { field: 'x', operator: 'exists' }, then: 'c', else: 'd' },
    { id: 'c', type: 'end', result: 'c' },
    { id: 'd', type: 'end', result: 'd' },
  ]};
  assert(executeWorkflow(legacy, {}).result === 'd', 'empty dependsOn no-op');

  // entry is the end node
  const onlyEnd = { id: 'w', entry: 'e', nodes: [{ id: 'e', type: 'end', result: 42 }] };
  assert(executeWorkflow(onlyEnd).result === 42, 'entry end');

  // single-element next array triggers single-end rule
  const oneArr = { id: 'w', entry: 'a', nodes: [
    { id: 'a', type: 'trigger', next: ['b'] },
    { id: 'b', type: 'end', result: 1 },
    { id: 'c', type: 'end', result: 2 },
  ]};
  let threw = false;
  try { validateWorkflow(oneArr); } catch (e) { threw = /exactly one end/.test(e.message); }
  assert(threw, 'single-element array next requires one end');

  // self-loop via next is a cycle
  const selfLoop = { id: 'w', entry: 'a', nodes: [
    { id: 'a', type: 'trigger', next: 'a' },
    { id: 'b', type: 'end' },
  ]};
  threw = false;
  try { validateWorkflow(selfLoop); } catch (e) { threw = /cycle is present: a -> a/.test(e.message); }
  assert(threw, 'self loop cycle');

  // diamond join via dependsOn on the end node itself
  const depOnEnd = { id: 'w', entry: 's', nodes: [
    { id: 's', type: 'trigger', next: ['p', 'q'] },
    { id: 'p', type: 'action', next: 'e' },
    { id: 'q', type: 'action', next: 'e' },
    { id: 'e', type: 'end', result: 'ok', dependsOn: ['p', 'q'] },
  ]};
  const r = executeWorkflow(depOnEnd, {});
  assert(r.status === 'completed' && r.trace.length === 4, 'end with dependsOn');

  console.log('edge cases OK');
});
"
